// Turn-based rules. One accepted action advances exactly one actor's turn.
export const SAVE='arena-heir-duels-v1',META='arena-heir-unlocks';
export const CLASSES={dwarf:{name:'Borin',title:'Dwarf',trait:'Iron bones · +3 armor',base:[5,2,3,4,1]},ranger:{name:'Rowan',title:'Ranger',trait:'Long stride · +1 movement',base:[2,5,4,2,1]},mage:{name:'Aster',title:'Mage',trait:'Arcane mind · +4 spell damage',base:[1,3,3,2,6]},thorn:{name:'Thornkeeper',title:'Forest Master',trait:'Living bark · recover 2 health when guarding',base:[4,3,3,4,3]}};
export const ATTRS=['strength','speed','defense','vitality','magic'];
export const SPELLS={lightning:{name:'Lightning',cost:20,price:65,tier:1,desc:'A bolt of lightning. Reliable damage at any distance.',cooldown:1},sleep:{name:'Sleep',cost:28,price:90,tier:1,desc:'Skip the enemy’s next turn. Damage wakes them.',cooldown:3},frost:{name:'Frost',cost:18,price:80,tier:1,desc:'Deal damage and halve movement for 2 turns.',cooldown:2},shield:{name:'Aegis',cost:16,price:75,tier:1,desc:'Absorb up to 18 damage from the next hit.',cooldown:2},meteor:{name:'Meteor',cost:32,price:200,tier:2,desc:'A heavy blast. Unlocked by the first crown.',cooldown:2}};
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export function newRun(hero,meta={}){if(!Object.hasOwn(CLASSES,hero)||hero==='thorn'&&!meta.thorn)throw Error('Locked fighter');return {v:1,hero,level:1,gold:0,points:0,attrs:Object.fromEntries(ATTRS.map((a,i)=>[a,CLASSES[hero].base[i]])),gear:{melee:0,ranged:hero==='ranger'?1:0,defense:0,boots:0},spells:hero==='mage'?['lightning']:[],crown:false,dead:false,tournament:null,offer:null,battle:null,serial:0,result:null};}
export function stats(r){const a=r.attrs,g=r.gear;return {hp:55+a.vitality*9,energy:85+a.speed*4,melee:7+a.strength*2+g.melee*7,ranged:g.ranged?8+a.speed*2+g.ranged*5:0,armor:a.defense+g.defense*3+(r.hero==='dwarf'?3:0),magic:8+a.magic*3+(r.hero==='mage'?4:0),stride:Math.max(1,Math.floor(a.speed/3)+1+g.boots+(r.hero==='ranger'?1:0))};}
export function gearName(hero,slot,tier){const stems={melee:hero==='mage'?'staff':hero==='ranger'?'blade':'axe',ranged:hero==='mage'?'wand':hero==='ranger'?'bow':'throwing axe',defense:hero==='mage'?'robe':hero==='ranger'?'leather':'armor',boots:'boots'};if(!tier)return slot==='ranged'?'Not owned':slot==='defense'?'Travel clothes':slot==='boots'?'Old boots':`Worn ${stems[slot]}`;return `${['','Ironbark','Moonsteel','Royal'][tier]} ${stems[slot]}`;}
export function shop(r,category){if(category==='magic')return Object.entries(SPELLS).map(([id,s])=>({id,...s,owned:r.spells.includes(id),locked:s.tier>(r.crown?2:1)}));const slots=category==='weapons'?['melee','ranged']:['defense','boots'];return slots.flatMap(slot=>[1,2,3].map(tier=>({id:slot+':'+tier,slot,tier,name:gearName(r.hero,slot,tier),price:([0,45,110,220][tier])+(slot==='ranged'?15:0),owned:r.gear[slot]>=tier,locked:tier>(r.crown?3:1),desc:slot==='boots'?'Move and jump farther.':slot==='defense'?'Reduce damage from incoming attacks.':slot==='ranged'?'Unlock a ranged attack.':'Increase close-range damage.'})));}
export function buy(r,category,id){if(r.dead||r.battle||r.tournament)return false;const i=shop(r,category).find(i=>i.id===id);if(!i||i.owned||i.locked||r.gold<i.price)return false;r.gold-=i.price;if(category==='magic')r.spells.push(id);else r.gear[i.slot]=i.tier;return true;}
export function allocate(r,key){if(!ATTRS.includes(key)||r.points<1||r.battle||r.dead)return false;r.attrs[key]++;r.points--;return true;}
export function offer(r){if(r.dead||r.battle||r.tournament)return null;const n=++r.serial,hero=['dwarf','ranger','mage'][(n-1)%3],o=newRun(hero);o.level=Math.max(1,r.level-(n%3===1?1:0));for(let i=1;i<o.level;i++){o.attrs.strength++;o.attrs.vitality++;if(i%2)o.attrs.defense++;else o.attrs.speed++;}o.gear.melee=Math.min(r.crown?2:1,Math.floor(o.level/4));o.gear.defense=Math.min(2,Math.floor(o.level/5));o.name=['Flint','Lark','Vesper'][(n-1)%3];o.reward=35+o.level*12;o.loss=20+o.level*5;o.id='duel-'+n;r.offer=o;return o;}
export function enterTournament(r){if(r.level<3||r.dead||r.crown||r.battle||r.tournament||r.points)return false;r.tournament={round:0};r.offer=null;r.result=null;return true;}
export function tournamentOffer(r){if(!r.tournament)return null;const round=r.tournament.round,o=newRun(round===2?'thorn':round===0?'ranger':'dwarf',{thorn:true});o.level=round+3;o.name=['Ash the Swift','Granite Guard','Thornkeeper'][round];o.attrs.strength+=round+1;o.attrs.vitality+=round+1;o.gear.melee=1;o.gear.defense=round?1:0;if(round===2)o.spells=['frost','shield'];o.id='crown-'+round;o.reward=round===2?300:55+round*20;o.loss=0;o.master=round===2;return o;}
function fighter(r,x){return {hero:r.hero,gear:{...r.gear},stats:stats(r),spells:[...r.spells],hp:stats(r).hp,energy:stats(r).energy,x,guard:false,shield:0,sleep:0,frost:0,cd:{}};}
export function startFight(r){if(r.dead||r.battle||r.points)return false;const o=r.tournament?tournamentOffer(r):r.offer;if(!o)return false;r.battle={p:fighter(r,4),e:fighter(o,14),opponent:o,turn:'p',count:1,log:'Your turn',outcome:null,events:[],seed:(r.serial+1)*7919+(r.tournament?.round||0),settled:false};r.result=null;return true;}
export function actions(b,who=b.turn){const a=b[who],e=b[who==='p'?'e':'p'],d=Math.abs(a.x-e.x),near=d<=2;const defs=[{id:'walk',name:'Advance',cost:3,desc:`Move ${a.stats.stride} spaces toward your rival.`},{id:'jump',name:'Jump',cost:8,desc:`Leap ${a.stats.stride+2} spaces toward your rival.`},{id:'retreat',name:'Retreat',cost:3,desc:'Step away. Give up this turn to gain distance.'},{id:'guard',name:'Guard',cost:0,desc:'Reduce the next attack and recover 8 energy.'},{id:'rest',name:'Rest',cost:0,desc:'Recover 24 energy. Leave yourself open.'}];for(const [id,name,cost,mul,ch]of [['quick','Quick strike',5,.7,92],['normal','Strike',9,1,80],['heavy','Heavy strike',16,1.5,62]])defs.push({id,name,cost,near:true,damage:Math.max(1,Math.round(a.stats.melee*mul-e.stats.armor*.55)),chance:clamp(ch+(a.stats.stride-e.stats.stride)*2,45,97),desc:id==='heavy'?'More damage. Greater risk.':'A close-range blow.'});if(a.stats.ranged)defs.push({id:'shoot',name:'Shoot',cost:9,damage:Math.max(1,a.stats.ranged-Math.round(e.stats.armor*.5)),chance:near?62:88,desc:near?'Harder to aim this close.':'Attack without closing the distance.'});for(const id of a.spells){const s=SPELLS[id];defs.push({id,name:s.name,cost:s.cost,damage:['lightning','frost','meteor'].includes(id)?Math.max(1,Math.round(a.stats.magic*(id==='meteor'?1.7:id==='frost'?.55:1)-e.stats.armor*.25)):undefined,chance:id==='sleep'?90:100,desc:s.desc,spell:true});}return defs.map(d=>({...d,disabled:!!b.outcome||a.energy<d.cost||d.near&&!near||(a.cd[d.id]||0)>0||(d.id==='retreat'&&(a.x===0||a.x===18)),reason:d.near&&!near?'Too far':a.cd[d.id]>0?`${a.cd[d.id]} turn cooldown`:a.energy<d.cost?'Low energy':''}));}
function random(b){b.seed=(Math.imul(b.seed,1664525)+1013904223)>>>0;return b.seed/4294967296;}
export function act(b,id,who=b.turn){if(b.outcome||b.turn!==who)return false;const a=b[who],other=who==='p'?'e':'p',e=b[other],move=actions(b,who).find(v=>v.id===id);if(!move||move.disabled)return false;const from=a.x;b.events=[];a.energy-=move.cost;a.guard=false;for(const k in a.cd)a.cd[k]=Math.max(0,a.cd[k]-1);const dir=Math.sign(e.x-a.x)||1,step=Math.max(1,Math.floor(a.stats.stride/(a.frost?2:1)));if(a.frost)a.frost--;
let text=`${who==='p'?'You':b.opponent.name}: ${move.name}`;
if(id==='walk'||id==='jump'){const distance=step+(id==='jump'?2:0);a.x=clamp(a.x+dir*Math.min(distance,Math.max(0,Math.abs(e.x-a.x)-1)),0,18);}
else if(id==='retreat')a.x=clamp(a.x-dir*step,0,18);
else if(id==='guard'){a.guard=true;a.energy=Math.min(a.stats.energy,a.energy+8);if(a.hero==='thorn')a.hp=Math.min(a.stats.hp,a.hp+2);}
else if(id==='rest')a.energy=Math.min(a.stats.energy,a.energy+24);
else if(id==='shield'){a.shield=18;a.cd[id]=SPELLS[id].cooldown+1;}
else {const hit=random(b)*100<(move.chance||100);if(move.spell)a.cd[id]=SPELLS[id].cooldown+1;if(!hit)text+=' · Miss!';else if(id==='sleep'){e.sleep=1;text+=' · Asleep';}else{let damage=Math.max(1,Math.round(move.damage*(e.guard?.35:1)));if(e.shield){const absorbed=Math.min(e.shield,damage);damage-=absorbed;e.shield=0;}e.hp=Math.max(0,e.hp-damage);e.sleep=0;e.guard=false;if(id==='frost')e.frost=2;text+=` · ${damage} damage`;b.events.push({type:'hit',target:other,damage});}}
b.events.unshift({type:'action',who,id,from,to:a.x});b.log=text;if(e.hp<=0)b.outcome=who==='p'?'win':'loss';else {b.turn=other;b.count++;if(e.sleep){e.sleep=0;for(const k in e.cd)e.cd[k]=Math.max(0,e.cd[k]-1);b.log+=' · '+(other==='e'?b.opponent.name:'You')+' missed a turn';b.turn=who;b.count++;}}return true;}
export function ai(b){const all=actions(b,'e').filter(a=>!a.disabled),a=b.e,e=b.p;if(a.energy<20)return 'rest';if(a.hp<a.stats.hp*.35&&!a.shield&&all.some(v=>v.id==='shield'))return 'shield';if(all.some(v=>v.id==='lightning')&&a.energy>35)return 'lightning';if(all.some(v=>v.id==='frost')&&!e.frost)return 'frost';if(Math.abs(a.x-e.x)<=2)return e.hp<15?'quick':'normal';if(all.some(v=>v.id==='shoot'))return 'shoot';return a.energy>35?'jump':'walk';}
export function settle(r,meta){const b=r.battle;if(!b?.outcome||b.settled)return false;b.settled=true;const won=b.outcome==='win',o=b.opponent;let gold=0;if(won){gold=o.reward;r.gold+=gold;r.level++;r.points+=3;if(r.tournament){r.tournament.round++;if(o.master){r.crown=true;meta.thorn=true;r.tournament=null;}}}else if(r.tournament){r.dead=true;r.tournament=null;}else{gold=-Math.min(r.gold,o.loss);r.gold+=gold;}r.result={won,gold,master:won&&!!o.master,dead:r.dead,name:o.name};r.battle=null;r.offer=null;return r.result;}
export function surrender(r,meta){if(!r.battle)return false;r.battle.outcome='loss';return settle(r,meta);}
export function load(raw,meta={}){try{const r=JSON.parse(raw);if(r.v!==1||!Object.hasOwn(CLASSES,r.hero)||r.hero==='thorn'&&!meta.thorn)return null;for(const k of ['level','gold','points','serial'])if(!Number.isSafeInteger(r[k])||r[k]<0||r[k]>1e7)return null;if(r.level<1||typeof r.dead!=='boolean'||typeof r.crown!=='boolean'||!r.attrs||!r.gear||!Array.isArray(r.spells))return null;if(ATTRS.some(k=>!Number.isInteger(r.attrs[k])||r.attrs[k]<1||r.attrs[k]>1e6)||['melee','ranged','defense','boots'].some(k=>!Number.isInteger(r.gear[k])||r.gear[k]<0||r.gear[k]>3)||r.spells.some(s=>!Object.hasOwn(SPELLS,s)))return null;if(r.tournament&&(!Number.isInteger(r.tournament.round)||r.tournament.round<0||r.tournament.round>2||r.crown||r.dead))return null;if(r.battle){const b=r.battle;if(!['p','e'].includes(b.turn)||!Number.isInteger(b.seed)||!b.opponent||!['win','loss',null].includes(b.outcome))return null;for(const k of ['p','e']){const a=b[k];if(!a||!Number.isFinite(a.hp)||a.hp<0||!Number.isFinite(a.energy)||a.energy<0||!Number.isInteger(a.x)||a.x<0||a.x>18||!a.stats||!a.cd||!Array.isArray(a.spells)||a.spells.some(s=>!Object.hasOwn(SPELLS,s)))return null;for(const n of ['hp','energy','melee','ranged','armor','magic','stride'])if(!Number.isFinite(a.stats[n])||a.stats[n]<0)return null;}b.events=[];}return r;}catch{return null;}}
